### GameBarrier Implementation

```java
public class GameBarrier {
    private static final int GAME_NOTREADY = 0;
    private static final int GAME_FILLING = 1;
    private static final int GAME_FILLED = 2;

    private Lock mutex;
    private int state;
    private Condition cv;
    private int NumWaiters;
    private int NumPlaying;

    public GameBarrier(Lock lock) {
        this.mutex = lock;
        this.state = GAME_NOTREADY;
        this.cv = new Condition();
        this.NumWaiters = 0;
        this.NumPlaying = 0;
    }

    public void waitToPlay() {
        mutex.acquire();
        try {
            NumWaiters++;
            while (state == GAME_NOTREADY || state == GAME_FILLED) {
                cv.wait(mutex);
            }
            NumWaiters--;
            NumPlaying++;
            if (NumPlaying == 4) {
                // All 4 players moved to the console
                state = GAME_FILLED;
            }
            if (NumWaiters >= 4 && state == GAME_FILLING) {
                cv.broadcast();
            }
        } finally {
            mutex.release();
        }
    }

    public void donePlaying() {
        mutex.acquire();
        try {
            NumPlaying--;
            if (NumPlaying == 0) {
                state = NumWaiters >= 4 ? GAME_FILLING : GAME_NOTREADY;
                cv.broadcast();
            }
        } finally {
            mutex.release();
        }
    }
}
```

### ConsoleBarrier Implementation

```java
public class ConsoleBarrier {
    private static final int CONSOLE_WAIT = 0;
    private static final int CONSOLE_ALLOW = 1;

    private Lock mutex;
    private int state;
    private Condition cv;
    private int NumAtConsole;

    public ConsoleBarrier(Lock lock) {
        this.mutex = lock;
        this.state = CONSOLE_WAIT;
        this.cv = new Condition();
        this.NumAtConsole = 0;
    }

    public void waitAtConsole() {
        mutex.acquire();
        try {
            NumAtConsole++;
            if (NumAtConsole == 4) {
                state = CONSOLE_ALLOW;
                cv.broadcast();
            } else {
                while (state == CONSOLE_WAIT) {
                    cv.wait(mutex);
                }
            }
            NumAtConsole--;
            if (NumAtConsole == 0) {
                state = CONSOLE_WAIT;
            }
        } finally {
            mutex.release();
        }
    }
}
```

