import java.util.ArrayList;

// Extend the existing Knapsack class
public class ValueKnapsack extends Knapsack {
    // ArrayList to keep track of item values
    private ArrayList<Integer> itemValues;

    // Constructor for ValueKnapsack
    public ValueKnapsack(int weightCapacity) {
        super(weightCapacity); // Call the superclass constructor
        itemValues = new ArrayList<Integer>(); // Initialize itemValues
    }

    // Add items with their values
    public void addItem(String name, int weight, int value) {
        super.addItem(name, weight); // Call superclass addItem method
        itemValues.add(new Integer(value)); // Add value to itemValues
    }

    // Remove items by name and their corresponding value
    @Override
    public void removeItem(String name) {
        int itemIndex = itemNames.indexOf(name); // Find item index
        super.removeItem(name); // Use superclass removeItem method
        itemValues.remove(itemIndex); // Remove value based on index
    }

    // Additional method to get the total value
    public int getTotalValue() {
        int totalValue = 0;
        for (Integer value : itemValues) {
            totalValue += value;
        }
        return totalValue;
    }
}
```

