public class AcronymExtractor {

    public static String extractAcronym(String input) {
        StringBuilder acronym = new StringBuilder();

        // Add the first character if it's not a '#' character
        if (input.length() > 0 && input.charAt(0) != '#') {
            acronym.append(input.charAt(0));
        }

        // Iterate through the string starting from the second character
        for (int i = 1; i < input.length(); i++) {
            // Check if the current character is preceded by a '#'
            if (input.charAt(i - 1) == '#' && input.charAt(i) != '#') {
                acronym.append(input.charAt(i));
            }
        }

        return acronym.toString();
    }

    public static void main(String[] args) {
        System.out.println(extractAcronym("Not#a##Number")); // Should print "NaN"
    }
}
```

